package com.coraline.feast;
import net.minecraft.nbt.*;
import net.minecraft.gametest.framework.*;
import net.minecraftforge.gametest.GameTestHolder;
import java.util.*;
@GameTestHolder("coraline")
@net.minecraftforge.gametest.PrefixGameTestTemplate(false)
public final class HousePartyLedgerGameTests {
    static CompoundTag party(){var n=new CompoundTag();HousePartyLedger.begin(n,new UUID(0,1),7,123,12);return n;}
    static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    @GameTest(template="empty") public static void clockPausesAndPersists(GameTestHelper h){var n=party();for(int i=0;i<100;i++)HousePartyLedger.advance(n,20,true,false,false);check(n.getLong("Clock")==2000,"active clock");var saved=n.copy();HousePartyLedger.advance(saved,20,true,false,true);check(saved.getLong("Clock")==2000,"confrontation paused");saved.putBoolean("Suspended",true);HousePartyLedger.advance(saved,20,true,false,false);check(saved.getInt("SocialElapsed")==2000,"suspension paused");h.succeed();}
    @GameTest(template="empty") public static void socialQueuesFeastExactlyOnce(GameTestHelper h){var n=party();for(int i=0;i<1300;i++)HousePartyLedger.advance(n,20,true,false,false);check(n.getInt("SocialElapsed")==HousePartyLedger.SOCIAL_TICKS&&n.getBoolean("FeastDue"),"social cap");check(n.getInt("FeastElapsed")==0,"no phantom feast");for(int i=0;i<400;i++)HousePartyLedger.advance(n,20,false,true,false);check(n.getInt("FeastElapsed")==n.getInt("FeastDuration"),"feast cap");h.succeed();}
    @GameTest(template="empty") public static void absenceRangeAndSuspicionBias(GameTestHelper h){for(int i=0;i<=100;i++){double u=i/100.;int low=HousePartyLedger.absenceDelay(0,u),high=HousePartyLedger.absenceDelay(1,u);check(low>=3600&&low<=12000&&high>=3600&&high<=12000,"bounded 3–10 minute grace");check(high<=low,"suspicion never lengthens same roll");}check(HousePartyLedger.absenceDelay(.5,Double.NaN)>=3600,"nonfinite roll safe");h.succeed();}
    @GameTest(template="empty") public static void returnDoesNotEraseSearch(GameTestHelper h){var n=party();HousePartyLedger.absence(n,true,false,.5,.5,20,25);for(int i=0;i<179;i++)check(!HousePartyLedger.absence(n,false,false,1,0,20,50),"early absence");check(HousePartyLedger.absence(n,false,false,1,0,20,50),"absence expires once");check(!HousePartyLedger.absence(n,true,true,1,0,20,25)&&n.getBoolean("AbsenceReported"),"return cannot cancel search");HousePartyLedger.reconciled(n);check(!n.getBoolean("AbsenceReported")&&!n.contains("AbsenceRemaining"),"reconciliation resets next incident");h.succeed();}
    @GameTest(template="empty") public static void briefActionCannotReport(GameTestHelper h){var n=party();var g=HousePartyLedger.addGuest(n,"resident",null,0);check(HousePartyLedger.observe(g,"drawer","",10,0,10,150)==HousePartyLedger.Notice.NONE,"recognition required");HousePartyLedger.observe(g,"","",10,10,5,150);check(!g.contains("WarningUntil")&&!g.getBoolean("ReportPending"),"brief glance no report");h.succeed();}
    @GameTest(template="empty") public static void complianceClearsOnlyCurrentIncident(GameTestHelper h){var n=party();var g=HousePartyLedger.addGuest(n,"resident",null,0);check(HousePartyLedger.observe(g,"drawer","",10,0,20,150)==HousePartyLedger.Notice.WARN,"warning first");check(HousePartyLedger.observe(g,"","",11,50,5,150)==HousePartyLedger.Notice.COMPLIED,"complied");check(g.getInt("Patience")==1&&!g.getBoolean("ReportPending")&&!g.contains("Incident"),"patience retained without accusation");h.succeed();}
    @GameTest(template="empty") public static void reportIsPersistedAndReceivedOnce(GameTestHelper h){var n=party();var g=HousePartyLedger.addGuest(n,"resident",null,0);HousePartyLedger.observe(g,"forbidden","rat_communication",10,0,20,150);g=g.copy();check(HousePartyLedger.observe(g,"forbidden","rat_communication",14,149,5,150)==HousePartyLedger.Notice.NONE,"warning interval");check(HousePartyLedger.observe(g,"forbidden","rat_communication",14,150,5,150)==HousePartyLedger.Notice.REPORT,"continued offense");check(g.getLong("ObservedPosition")==14&&g.getString("IdentifiedSecret").equals("rat_communication"),"only observed evidence");check(HousePartyLedger.receiveReport(g)&&!HousePartyLedger.receiveReport(g),"physical receive once");HousePartyLedger.finishReport(g);check(!g.contains("Incident")&&!g.getBoolean("ReportPending"),"finished report clears");h.succeed();}
    @GameTest(template="empty") public static void warningsNeverBecomeInstant(GameTestHelper h){var n=party();var g=HousePartyLedger.addGuest(n,"resident",null,0);g.putInt("Patience",10);HousePartyLedger.observe(g,"outside","",10,200,20,150);check(g.getLong("WarningUntil")>=300,"at least five seconds despite impatience");h.succeed();}
    @GameTest(template="empty") public static void guestIdentityIsOwnerAndSerialScoped(GameTestHelper h){var a=party();var b=party();var first=HousePartyLedger.addGuest(a,"resident",null,0);check(first.getUUID("Id").equals(HousePartyLedger.addGuest(b,"resident",null,0).getUUID("Id")),"stable across reload");b.putInt("Serial",8);check(!first.getUUID("Id").equals(HousePartyLedger.addGuest(b,"resident",null,0).getUUID("Id")),"new event new identity");check(!HousePartyLedger.owned(a,new UUID(0,2),7),"foreign owner rejected");h.succeed();}
    @GameTest(template="empty") public static void secretClaimsCappedPerGuestAndParty(GameTestHelper h){var n=party();for(int i=0;i<3;i++){var g=HousePartyLedger.addGuest(n,"resident",null,i);check(HousePartyLedger.mayClaimSecret(n,g),"eligible unique guest");HousePartyLedger.claimedSecret(n,g,"blind_spots");check(!HousePartyLedger.mayClaimSecret(n,g),"one per guest");}check(!HousePartyLedger.mayClaimSecret(n,HousePartyLedger.addGuest(n,"resident",null,4)),"three per party");h.succeed();}
    @GameTest(template="empty") public static void foodWitnessAndWarningWindow(GameTestHelper h){var n=party();for(int i=0;i<100;i++)check(HousePartyLedger.foodTaking(n,i,false)==HousePartyLedger.FoodNotice.ALLOW,"unseen taking not magically noticed");check(n.getLongArray("WitnessedFoodTakes").length==0,"unseen counter untouched");for(int i=0;i<3;i++)check(HousePartyLedger.foodTaking(n,100+i,true)==HousePartyLedger.FoodNotice.ALLOW,"three reasonable servings");check(HousePartyLedger.foodTaking(n,104,true)==HousePartyLedger.FoodNotice.WARN,"fourth warning");check(HousePartyLedger.foodTaking(n,105,true)==HousePartyLedger.FoodNotice.BLOCK,"continued excess temporarily blocked");check(HousePartyLedger.foodTaking(n,600,true)==HousePartyLedger.FoodNotice.ALLOW,"rolling window expires");h.succeed();}
    @GameTest(template="empty") public static void malformedTickDeltasRejected(GameTestHelper h){var n=party();boolean bad=false;try{HousePartyLedger.advance(n,21,true,false,false);}catch(IllegalArgumentException e){bad=true;}check(bad,"unbounded elapsed rejected");bad=false;try{HousePartyLedger.absence(n,false,false,0,0,-1,0);}catch(IllegalArgumentException e){bad=true;}check(bad,"negative absence rejected");h.succeed();}
}
